const IMG = {
      "ganesh-pooja": "data:image/webp;base64,",
      "mamera": "data:image/webp;base64,",
      "sangeet": "data:image/webp;base64,",
      "haldi": "data:image/webp;base64,",
      "wedding": "data:image/webp;base64,"
    };
    'use strict';
    const $ = id => document.getElementById(id);
    const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const opening = $('opening'), site = $('site'), doors = $('doors'); let opened = false, transitioning = false; const eb = $('entranceBackground'); eb.muted = true; if (reduced) eb.pause(); else eb.play().catch(() => { });
    const weddingMusic = $('weddingMusic'), musicButton = $('musicButton');
    let musicPlaying = false;

    function updateMusicButton() {
      musicButton.dataset.playing = String(musicPlaying);
      musicButton.setAttribute('aria-pressed', String(musicPlaying));
      musicButton.setAttribute('aria-label', musicPlaying ? 'Turn music off' : 'Turn music on');
      musicButton.title = musicPlaying ? 'Music on' : 'Music off';
    }

    function startWeddingMusic() {
      weddingMusic.volume = 0.62;
      const playback = weddingMusic.play();
      if (playback && typeof playback.then === 'function') {
        playback.then(() => {
          musicPlaying = true;
          updateMusicButton();
        }).catch(() => {
          musicPlaying = false;
          updateMusicButton();
        });
      } else {
        musicPlaying = true;
        updateMusicButton();
      }
    }

    function toggleWeddingMusic() {
      if (weddingMusic.paused) {
        startWeddingMusic();
      } else {
        weddingMusic.pause();
        musicPlaying = false;
        updateMusicButton();
      }
    }

    musicButton.addEventListener('click', toggleWeddingMusic);
    weddingMusic.addEventListener('pause', () => {
      musicPlaying = false;
      updateMusicButton();
    });
    weddingMusic.addEventListener('play', () => {
      musicPlaying = true;
      updateMusicButton();
    });
    updateMusicButton();

    let t1, t2;
    function finishOpening() {
      if (opened) return;
      opened = true;
      opening.classList.add('open');
      opening.inert = true;
      site.inert = false;
      document.body.classList.remove('locked');
      // Start the invitation at the top of the Hershini & Vinit home section.
      // Do not focus an element or follow an anchor that could move the page down.
      if (location.hash) history.replaceState(null, '', location.pathname + location.search);
      document.documentElement.style.scrollBehavior = 'auto';
      window.scrollTo(0, 0);
      setTimeout(() => {
        window.scrollTo(0, 0);
        document.documentElement.style.scrollBehavior = '';
        opening.remove();
      }, 850);
    }
    function endDoors() { clearTimeout(t1); clearTimeout(t2); doors.style.transition = 'opacity .35s'; doors.style.opacity = '0'; setTimeout(() => doors.remove(), 300) }
    function showerPetals() {
      if (reduced) return;
      const colors = ['0', '1', '2'];
      for (let i = 0; i < 115; i++) {
        const petal = document.createElement('i');
        petal.className = 'petal-shower';
        petal.dataset.tone = colors[i % colors.length];
        petal.style.left = (Math.random() * 100) + 'vw';
        petal.style.setProperty('--shower-size', (8 + Math.random() * 13) + 'px');
        petal.style.setProperty('--shower-duration', (2.5 + Math.random() * 2.2) + 's');
        petal.style.setProperty('--shower-delay', (Math.random() * 1.15) + 's');
        petal.style.setProperty('--shower-drift', (-150 + Math.random() * 300) + 'px');
        petal.style.setProperty('--shower-rotation', (360 + Math.random() * 1080) + 'deg');
        document.body.appendChild(petal);
        setTimeout(() => petal.remove(), 6500);
      }
    }

    function openInvitation() {
      if (opened || transitioning) return;
      startWeddingMusic();
      transitioning = true; burstConfetti(innerWidth / 2, innerHeight * .48); opening.classList.add('transitioning'); eb.pause(); $('openInvite').disabled = true; doors.classList.add('show'); if (reduced) { finishOpening(); endDoors(); return }
      // Start the door movement after the entrance fades, then remove the
      // doors only after their 3.6-second CSS swing has completed.
      t1 = setTimeout(() => {
        showerPetals();
        doors.classList.add('swing');
        finishOpening();
        t2 = setTimeout(endDoors, 3900);
      }, 1200);
    }
    $('skipTransition').addEventListener('click', () => { finishOpening(); endDoors() });
    $('openInvite').addEventListener('click', openInvitation); document.querySelector('.skip-link').addEventListener('click', finishOpening);

    const canvas = $('scratchCanvas'), card = $('scratchCard'), ctx = canvas.getContext('2d'); let scratching = false, dateRevealed = false, lastPoint = null, distance = 0;
    function cover() { if (dateRevealed) return; const r = card.getBoundingClientRect(), d = Math.min(devicePixelRatio || 1, 2); canvas.width = r.width * d; canvas.height = r.height * d; ctx.setTransform(d, 0, 0, d, 0, 0); const g = ctx.createLinearGradient(0, 0, r.width, r.height); g.addColorStop(0, '#aa7340'); g.addColorStop(.45, '#eed2a0'); g.addColorStop(1, '#bb884d'); ctx.fillStyle = g; ctx.fillRect(0, 0, r.width, r.height); ctx.fillStyle = '#612033'; ctx.textAlign = 'center'; ctx.font = 'italic 29px Georgia'; ctx.fillText('Scratch here', r.width / 2, r.height * .46); ctx.font = '13px Arial'; ctx.fillText('to reveal our wedding date', r.width / 2, r.height * .56); ctx.globalCompositeOperation = 'destination-out'; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.lineWidth = 42 }
    function revealDate() { if (dateRevealed) return; dateRevealed = true; card.classList.add('done'); canvas.tabIndex = -1; canvas.setAttribute('aria-hidden', 'true'); $('revealButton').textContent = 'Monday, 15th February'; $('revealButton').disabled = true; $('revealStatus').textContent = 'Wedding ceremony: Monday, 15th February, 5:00 PM onwards, India time.'; const r = card.getBoundingClientRect(); burstConfetti(r.left + r.width / 2, r.top + r.height / 2) }
    function scratch(e) { if (!scratching || dateRevealed) return; const r = canvas.getBoundingClientRect(), p = { x: e.clientX - r.left, y: e.clientY - r.top }; ctx.beginPath(); if (lastPoint) { ctx.moveTo(lastPoint.x, lastPoint.y); ctx.lineTo(p.x, p.y); ctx.stroke(); distance += Math.hypot(p.x - lastPoint.x, p.y - lastPoint.y) } else { ctx.arc(p.x, p.y, 21, 0, Math.PI * 2); ctx.fill() } lastPoint = p; if (distance > r.width * 2.7) revealDate() }
    canvas.addEventListener('pointerdown', e => { scratching = true; lastPoint = null; canvas.setPointerCapture(e.pointerId); scratch(e) }); canvas.addEventListener('pointermove', scratch); for (const name of ['pointerup', 'pointercancel', 'lostpointercapture']) canvas.addEventListener(name, () => { scratching = false; lastPoint = null }); canvas.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); revealDate() } }); $('revealButton').addEventListener('click', revealDate); cover(); addEventListener('resize', cover);
    const venueMap = ['https://www.google.com/maps/search/?api=1&query=Shoonya+Farm+Retreat'];
    const events = [
      { id: 'ganesh-pooja', title: 'Mandavo', date: 'Sunday, 14 February 2027', short: '14 FEBRUARY 2027', time: '7:30 AM onwards', color: '#a66a19', venue: 0, desc: 'Join us for Ganesh Pooja as we seek Lord Ganesha’s blessings for the wedding celebrations.' },
      { id: 'mamera', title: 'Mamera', date: 'Sunday, 14 February 2027', short: '14 FEBRUARY 2027', time: '2:30 PM onwards', color: '#8a2e38', venue: 0, desc: 'Celebrate the beautiful Gujarati Mamera tradition with blessings, gifts and love from the maternal family.' },
      { id: 'sangeet', title: 'Sangeet', date: 'Sunday, 14 February 2027', short: '14 FEBRUARY 2027', time: '7:00 PM onwards', color: '#49306f', venue: 0, desc: 'An evening of music, dance and joyful performances as our families come together to celebrate.' },
      { id: 'haldi', title: 'Haldi Ceremony', date: 'Monday, 15 February 2027', short: '15 FEBRUARY 2027', time: '9:00 AM onwards', color: '#87581c', venue: 0, desc: 'A morning of haldi and heartfelt blessings as our wedding day begins.' },
      { id: 'wedding', title: 'Wedding Ceremony', date: 'Monday, 15 February 2027', short: '15 FEBRUARY 2027', time: '5:00 PM onwards', color: '#741e2c', venue: 0, desc: 'Join us as the bride and groom take vows to be together and begin the next chapter of their lives.' }];
    const venues = ['Shoonya Farm Retreat'];
    for (const e of events) { const article = document.createElement('article'); article.className = 'event-card'; article.style.setProperty('--event-color', e.color); article.innerHTML = `<div class="event-art"><img src="${IMG[e.id]}" alt="Illustration for ${e.title}" loading="lazy" width="1024" height="1280"></div><div class="event-details"><p class="eyebrow">${e.short}</p><h3>${e.title}</h3><time>${e.time}</time><p class="event-venue">Shoonya Farm Retreat</p><button class="text-link" type="button" aria-label="View ${e.title} details">View celebration details ↗</button></div>`; article.querySelector('button').addEventListener('click', () => { $('modalImage').src = `${IMG[e.id]}`; $('modalImage').alt = `Illustration for ${e.title}`; $('modalDate').textContent = e.date; $('modalTitle').textContent = e.title; $('modalTime').textContent = e.time + (e.time.includes('onwards') ? ' · IST' : ''); $('modalText').textContent = e.desc; $('modalVenue').textContent = venues[e.venue]; $('modalMap').href = venueMap[e.venue]; $('eventModal').showModal() }); $('eventGrid').append(article) }
    for (const dialog of document.querySelectorAll('dialog')) { dialog.querySelector('[data-close]').addEventListener('click', () => dialog.close()); dialog.addEventListener('click', e => { const r = dialog.getBoundingClientRect(); if (e.target === dialog && (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom)) dialog.close() }) }
    $('menuButton').addEventListener('click', () => { $('mobileMenu').showModal(); $('menuButton').setAttribute('aria-expanded', 'true') }); $('mobileMenu').addEventListener('close', () => $('menuButton').setAttribute('aria-expanded', 'false')); $('mobileMenu').querySelectorAll('a').forEach(a => a.addEventListener('click', () => $('mobileMenu').close()));
    function burstConfetti(x, y) { if (reduced) return; const burst = document.createElement('div'); burst.className = 'confetti-burst'; burst.style.left = x + 'px'; burst.style.top = y + 'px'; for (let i = 0; i < 36; i++) { const bit = document.createElement('i'), angle = Math.random() * Math.PI * 2, distance = 70 + Math.random() * 180; bit.style.setProperty('--x', Math.cos(angle) * distance + 'px'); bit.style.setProperty('--y', Math.sin(angle) * distance + 100 + 'px'); bit.style.setProperty('--r', (-360 + Math.random() * 720) + 'deg'); bit.style.background = ['#741e2c', '#c59346', '#f0c87b', '#e6c0a2'][i % 4]; burst.appendChild(bit) } document.body.append(burst); setTimeout(() => burst.remove(), 1700) }


    const petalLayer = $('petalLayer');
    if (!reduced) {
      for (let i = 0; i < 22; i++) {
        const fall = document.createElement('span'), petal = document.createElement('i');
        fall.className = 'petal-fall'; petal.className = 'floating-petal';
        const size = 7 + Math.random() * 8;
        fall.style.left = (Math.random() * 100) + '%';
        fall.style.setProperty('--fall-time', (13 + Math.random() * 13) + 's');
        fall.style.setProperty('--fall-delay', (-Math.random() * 26) + 's');
        fall.style.setProperty('--drift', (-65 + Math.random() * 130) + 'px');
        petal.style.setProperty('--petal-size', size + 'px');
        petal.style.setProperty('--petal-opacity', (.28 + Math.random() * .26).toFixed(2));
        petal.style.setProperty('--sway-time', (3 + Math.random() * 4) + 's');
        petal.style.setProperty('--petal-turn', (Math.random() * 240) + 'deg');
        petal.dataset.tone = String(i % 3);
        fall.append(petal); petalLayer.append(fall);
      }
      document.addEventListener('visibilitychange', () => petalLayer.classList.toggle('page-hidden', document.hidden));
    } else { petalLayer.hidden = true }